def maxAverageOfPath(cost):
    N = len(cost)
    dp = [[0 for _ in range(N)] for _ in range(N)]
    dp[0][0] = cost[0][0]

    for i in range(1, N):
        dp[i][0] = dp[i-1][0] + cost[i][0]

    for j in range(1, N):
        dp[0][j] = dp[0][j-1] + cost[0][j]

    for i in range(1, N):
        for j in range(1, N):
            dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + cost[i][j]

    max_avg = 0
    for i in range(N):
        for j in range(N):
            total = 0
            path_length = 0
            x, y = i, j
            while x >= 0 and y >= 0:
                total += cost[x][y]
                path_length += 1
                if x == 0 and y == 0:
                    break
                if x == 0:
                    y -= 1

